def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0
    from collections import defaultdict
    import heapq
    color_adj = [defaultdict(list) for _ in range(n)]
    for u, v, w, color in edges:
        color_adj[u][color].append((v, w))
        if u != v:
            color_adj[v][color].append((u, w))
    INF = 10**18
    dist = [{} for _ in range(n)]
    min_dist = [INF] * n
    pq = []
    for c, elist in color_adj[s].items():
        for v, w in elist:
            newcost = w
            if newcost < dist[v].get(c, INF):
                dist[v][c] = newcost
                heapq.heappush(pq, (newcost, v, c))
    while pq:
        cost, u, c = heapq.heappop(pq)
        if cost > dist[u].get(c, INF):
            continue
        if cost < min_dist[u]:
            min_dist[u] = cost
            for c2, elist in color_adj[u].items():
                for v, w in elist:
                    newcost = cost + switch_cost + w
                    if newcost < dist[v].get(c2, INF):
                        dist[v][c2] = newcost
                        heapq.heappush(pq, (newcost, v, c2))
        if c in color_adj[u]:
            for v, w in color_adj[u][c]:
                newcost = cost + w
                if newcost < dist[v].get(c, INF):
                    dist[v][c] = newcost
                    heapq.heappush(pq, (newcost, v, c))
    if not dist[t]:
        return -1
    return min(dist[t].values())

def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("impossible to select")

    INF = float("-inf")

    def linear_max(arr, kk):
        m = len(arr)
        if kk == 0:
            return 0
        if kk > (m + 1) // 2 or m == 0:
            return INF
        # dp[i][j] = max sum using first i elements, exactly j selected
        dp = [[INF] * (kk + 1) for _ in range(m + 1)]
        dp[0][0] = 0
        for i in range(1, m + 1):
            dp[i][0] = 0
            max_j = min(kk, (i + 1) // 2)
            for j in range(1, max_j + 1):
                # skip current
                dp[i][j] = dp[i - 1][j]
                # take current
                if i == 1:
                    take = arr[0] if j == 1 else INF
                else:
                    take = dp[i - 2][j - 1] + arr[i - 1]
                if take > dp[i][j]:
                    dp[i][j] = take
        return dp[m][kk]

    s1 = linear_max(values[1:], k)
    s2 = linear_max(values[:-1], k)
    ans = max(s1, s2)
    if ans == INF:
        raise ValueError("impossible to select")
    return int(ans)

from collections import deque, defaultdict

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(sr, sc):
        dist = [[float('inf')] * C for _ in range(R)]
        dist[sr][sc] = 0
        q = deque([(sr, sc)])
        while q:
            r, col = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, col + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist[nr][nc] == float('inf'):
                    dist[nr][nc] = dist[r][col] + 1
                    q.append((nr, nc))
        return dist

    dist_start = bfs(0, 0)
    dist_end = bfs(R - 1, C - 1)
    ans = dist_start[R - 1][C - 1]

    label_cells = defaultdict(list)
    for i in range(R):
        for j in range(C):
            if grid[i][j] != -1:
                label_cells[grid[i][j]].append((i, j))

    for cells in label_cells.values():
        if len(cells) < 2:
            continue
        min1_s = min2_s = float('inf')
        min1_e = min2_e = float('inf')
        cell_min_s = cell_min_e = None
        for i, j in cells:
            ds = dist_start[i][j]
            de = dist_end[i][j]
            if ds < min1_s:
                min2_s = min1_s
                min1_s = ds
                cell_min_s = (i, j)
            elif ds < min2_s:
                min2_s = ds
            if de < min1_e:
                min2_e = min1_e
                min1_e = de
                cell_min_e = (i, j)
            elif de < min2_e:
                min2_e = de
        if min1_s == float('inf') or min1_e == float('inf'):
            continue
        cand = float('inf')
        if cell_min_s != cell_min_e:
            cand = min1_s + min1_e
        else:
            if min2_e < float('inf'):
                cand = min(cand, min1_s + min2_e)
            if min2_s < float('inf'):
                cand = min(cand, min2_s + min1_e)
        if cand < float('inf'):
            ans = min(ans, cand + c)

    return -1 if ans == float('inf') else int(ans)

def max_sessions(intervals, gap):
    if not intervals:
        return 0
    intervals = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = None
    for start, end in intervals:
        if last_end is None or start >= last_end + gap:
            count += 1
            last_end = end
    return count

def smallest_balanced(s):
    n = len(s)
    if n % 2 == 1:
        raise ValueError
    t = list(s)
    ques_pos = []
    for i in range(n):
        if t[i] == '?':
            ques_pos.append(i)
            t[i] = '('
    bal = 0
    for c in t:
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError
    k = bal // 2
    if bal % 2 != 0 or k > len(ques_pos):
        raise ValueError
    for i in range(1, k + 1):
        t[ques_pos[-i]] = ')'
    bal = 0
    for c in t:
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError
    if bal != 0:
        raise ValueError
    return ''.join(t)

def longest_spaced_repeat(s, gap):
    n = len(s)
    max_L = 0
    for d in range(gap + 1, n):
        match_len = 0
        for p in range(n - d - 1, -1, -1):
            if s[p] == s[p + d]:
                match_len += 1
                L = min(match_len, d - gap)
                if L > max_L:
                    max_L = L
            else:
                match_len = 0
    return max_L

def min_insertions(s, allowed):
    n = len(s)
    if n <= 1:
        return 0
    allow = set(allowed)
    INF = float('inf')
    dp = [[INF] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            cand = INF
            if s[i] == s[j]:
                cand = 0 if i + 1 > j - 1 else dp[i + 1][j - 1]
            if s[i] in allow:
                cand = min(cand, 1 + dp[i + 1][j])
            if s[j] in allow:
                cand = min(cand, 1 + dp[i][j - 1])
            dp[i][j] = cand
    res = dp[0][n - 1]
    return -1 if res == INF else res

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("invalid amount")
        dot = amount.find(".")
        if dot == -1:
            if not amount or not all(c in "0123456789" for c in amount):
                raise ValueError("invalid amount")
            cents = int(amount) * 100
        else:
            whole = amount[:dot]
            frac = amount[dot + 1:]
            if (
                not whole
                or not frac
                or len(frac) > 2
                or not all(c in "0123456789" for c in whole)
                or not all(c in "0123456789" for c in frac)
            ):
                raise ValueError("invalid amount")
            if len(frac) == 1:
                cents = int(whole) * 100 + int(frac) * 10
            else:
                cents = int(whole) * 100 + int(frac)
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        # Same start is always a conflict (including two pure insertions).
        # Overlapping delete ranges conflict; merely touching does not.
        if ordered[i][0] == prev[0] or ordered[i][0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    # Apply from the end so earlier original indices stay valid.
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

