def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

from collections import OrderedDict


class TTLCache:
    """Fixed-capacity LRU cache with optional per-entry TTL and an explicit clock."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        # key -> (value, stored_at, ttl); OrderedDict preserves LRU..MRU order
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        """Remove every entry that is dead at `now`. Counts as expirations."""
        dead = [
            key
            for key, (_, stored_at, ttl) in self._data.items()
            if ttl is not None and now >= stored_at + ttl
        ]
        for key in dead:
            del self._data[key]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive when provided")

        self._purge(now)

        if key in self._data:
            # Update in place: refresh value/time/ttl and mark MRU (no eviction).
            del self._data[key]
            self._data[key] = (value, now, ttl)
            return

        if len(self._data) >= self._capacity:
            self._data.popitem(last=False)  # evict LRU
            self._evictions += 1

        self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)

        if key not in self._data:
            self._misses += 1
            return None

        self._hits += 1
        value, stored_at, ttl = self._data.pop(key)
        self._data[key] = (value, stored_at, ttl)  # mark MRU
        return value

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._data)

class Leaderboard:
    def __init__(self):
        self._best = {}          # player -> best score
        self._time = {}          # player -> global order when current best was set
        self._clock = 0          # increments only on improving (or first) submits

    def submit(self, player, score):
        if player not in self._best or score > self._best[player]:
            self._best[player] = score
            self._time[player] = self._clock
            self._clock += 1
            return True
        return False

    def best(self, player):
        if player not in self._best:
            raise KeyError(player)
        return self._best[player]

    def rank(self, player):
        if player not in self._best:
            raise KeyError(player)
        b = self._best[player]
        return 1 + sum(1 for s in self._best.values() if s > b)

    def top(self, k):
        if k < 0:
            raise ValueError(k)
        if k == 0:
            return []
        ordered = sorted(
            self._best,
            key=lambda p: (-self._best[p], self._time[p]),
        )
        return [(p, self._best[p]) for p in ordered[:k]]

    def player_count(self):
        return len(self._best)

class MergeLedger:
    def __init__(self):
        self.parent = {}
        self.children = {}
        self.subtree_size = {}
        self.subtree_sum = {}
        self.history = []
        self.num_components = 0

    def _find(self, x):
        if x not in self.parent:
            raise KeyError(x)
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def add(self, x, value=0):
        if x in self.parent:
            raise ValueError(f"element {x} already exists")
        self.parent[x] = x
        self.children[x] = []
        self.subtree_size[x] = 1
        self.subtree_sum[x] = value
        self.num_components += 1

    def merge(self, a, b):
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        # Union by size
        if self.subtree_size[ra] < self.subtree_size[rb]:
            ra, rb = rb, ra
        # Attach rb under ra
        self.parent[rb] = ra
        self.children[ra].append(rb)
        self.subtree_size[ra] += self.subtree_size[rb]
        self.subtree_sum[ra] += self.subtree_sum[rb]
        self.history.append(rb)
        self.num_components -= 1
        return True

    def same(self, a, b):
        return self._find(a) == self._find(b)

    def component_size(self, x):
        return self.subtree_size[self._find(x)]

    def component_value(self, x):
        return self.subtree_sum[self._find(x)]

    def add_value(self, x, delta):
        if x not in self.parent:
            raise KeyError(x)
        u = x
        while True:
            self.subtree_sum[u] += delta
            if self.parent[u] == u:
                break
            u = self.parent[u]

    def components(self):
        return self.num_components

    def undo(self):
        if not self.history:
            raise RuntimeError("no merge to undo")
        rb = self.history.pop()
        ra = self.parent[rb]
        # Detach rb from ra
        self.parent[rb] = rb
        self.children[ra].pop()
        self.subtree_size[ra] -= self.subtree_size[rb]
        self.subtree_sum[ra] -= self.subtree_sum[rb]
        self.num_components += 1

class IntervalSet:
    def __init__(self):
        self._intervals = []  # sorted list of [lo, hi) pairs, disjoint and non-adjacent

    def _check(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be < hi")

    def add(self, lo, hi):
        self._check(lo, hi)
        new = []
        placed = False
        for a, b in self._intervals:
            if b < lo:
                # completely before, no touch
                new.append((a, b))
            elif hi < a:
                # completely after
                if not placed:
                    new.append((lo, hi))
                    placed = True
                new.append((a, b))
            else:
                # overlap or adjacent: merge
                lo = min(lo, a)
                hi = max(hi, b)
        if not placed:
            new.append((lo, hi))
        self._intervals = new

    def remove(self, lo, hi):
        self._check(lo, hi)
        new = []
        for a, b in self._intervals:
            if b <= lo or hi <= a:
                # no overlap
                new.append((a, b))
            else:
                # overlap: keep left remnant if any
                if a < lo:
                    new.append((a, lo))
                # keep right remnant if any
                if hi < b:
                    new.append((hi, b))
        self._intervals = new

    def contains(self, x):
        # binary search would be fine; linear is ok for clarity
        for a, b in self._intervals:
            if a <= x < b:
                return True
            if x < a:
                return False
        return False

    def total(self):
        return sum(b - a for a, b in self._intervals)

    def intervals(self):
        return list(self._intervals)

    def gaps(self, lo, hi):
        self._check(lo, hi)
        gaps = []
        cur = lo
        for a, b in self._intervals:
            if b <= lo:
                continue
            if a >= hi:
                break
            if cur < a:
                gaps.append((cur, min(a, hi)))
            cur = max(cur, b)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

import heapq

class TaskScheduler:
    def __init__(self):
        self._heap = []  # entries: (-priority, submit_seq, task_id)
        self._active = {}  # task_id -> (priority, submit_seq)
        self._seq = 0

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task {task_id!r} is already active")
        self._seq += 1
        self._active[task_id] = (priority, self._seq)
        heapq.heappush(self._heap, (-priority, self._seq, task_id))

    def reprioritize(self, task_id, priority):
        if task_id not in self._active:
            raise KeyError(task_id)
        _, submit_seq = self._active[task_id]
        self._active[task_id] = (priority, submit_seq)
        heapq.heappush(self._heap, (-priority, submit_seq, task_id))

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]

    def _clean(self):
        while self._heap:
            neg_p, seq, tid = self._heap[0]
            cur = self._active.get(tid)
            if cur is not None and cur[0] == -neg_p and cur[1] == seq:
                return
            heapq.heappop(self._heap)

    def pop(self):
        self._clean()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, tid = heapq.heappop(self._heap)
        del self._active[tid]
        return tid

    def peek(self):
        self._clean()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        return self._active[task_id][0]

    def __len__(self):
        return len(self._active)

class UndoStack:
    def __init__(self):
        self._stack = []
        self._history = []  # list of ('push',) or ('pop', value)

    def push(self, x) -> None:
        self._stack.append(x)
        self._history.append(('push',))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty stack")
        value = self._stack.pop()
        self._history.append(('pop', value))
        return value

    def peek(self):
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op = self._history.pop()
        if op[0] == 'push':
            self._stack.pop()
        else:  # 'pop'
            self._stack.append(op[1])

    def __len__(self) -> int:
        return len(self._stack)

class VersionedKV:
    """Key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self):
        self._working = {}
        self._snapshots = []  # index 0 unused; snapshots[v] is state at version v

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        self._snapshots.append(dict(self._working))
        return len(self._snapshots)

    def get_at(self, key, version):
        if not (1 <= version <= self.latest()):
            raise ValueError(f"invalid version: {version}")
        snap = self._snapshots[version - 1]
        if key not in snap:
            raise KeyError(key)
        return snap[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= self.latest()):
            raise ValueError(f"invalid version: {version}")
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._snapshots[version - 1])

    def latest(self) -> int:
        return len(self._snapshots)

def rank_scores(scores: list) -> list[int]:
    """Assign competition ranks (1224-style) to numeric scores.

    Rank of a score is 1 plus the number of scores strictly greater than it.
    Equal scores share a rank; the next lower distinct score skips ranks.
    """
    if not scores:
        return []

    for s in scores:
        # NaN is the only value not equal to itself
        if s != s:
            raise ValueError("NaN scores are not allowed")

    return [1 + sum(1 for s in scores if s > score) for score in scores]

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be >= 0")
    if width == 0 or not s:
        return ""

    def is_combining(ch: str) -> bool:
        return unicodedata.category(ch) in ("Mn", "Mc", "Me")

    # Segment into units: each unit is a list of code points (as a string slice via indices)
    units = []
    i = 0
    n = len(s)
    while i < n:
        # Start of a new unit
        start = i
        i += 1
        # Consume following combining marks
        while i < n and is_combining(s[i]):
            i += 1
        units.append(s[start:i])

    if width >= len(units):
        return s
    return "".join(units[:width])

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError
    if n <= 1 or k == 1:
        return n
    # For k large enough that 2^k > n, the root is 1
    if k >= n.bit_length():
        return 1
    # Binary search for largest r with r**k <= n.
    # Upper bound: 2**ceil(log2(n)/k) >= n**(1/k)
    lo = 1
    hi = 1 << ((n.bit_length() + k - 1) // k)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def round_robin(iterables):
    """Lazily interleave values from a list of iterables in round-robin order."""
    iterators = [iter(it) for it in iterables]
    while iterators:
        remaining = []
        for iterator in iterators:
            try:
                yield next(iterator)
                remaining.append(iterator)
            except StopIteration:
                pass
        iterators = remaining

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W <= 0:
        raise ValueError("total weight must be positive")

    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    threshold = W / 2
    cum = 0.0
    for v, w in pairs:
        cum += w
        if cum >= threshold - 1e-9:
            return v

import math

def vector_norm(v: list[float]) -> float:
    for x in v:
        if not math.isfinite(x):
            raise ValueError("vector entries must be finite")
    if not v:
        return 0.0
    max_abs = max(abs(x) for x in v)
    if max_abs == 0.0:
        return 0.0
    sum_sq = sum((x / max_abs) ** 2 for x in v)
    return max_abs * math.sqrt(sum_sq)

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0
    jobs = sorted(jobs, key=lambda x: x[0])
    heap: list[int] = []
    total = 0
    for d, p in jobs:
        max_slots = d * cap
        if len(heap) < max_slots:
            heapq.heappush(heap, p)
            total += p
        elif heap and p > heap[0]:
            total += p - heap[0]
            heapq.heapreplace(heap, p)
    return total

from collections import defaultdict

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + deltas[i]
    freq = defaultdict(int)
    count = 0
    for right in range(n + 1):
        left_add = right - lo
        if left_add >= 0:
            m = pref[left_add] % k
            freq[m] += 1
        left_rem = right - hi - 1
        if left_rem >= 0:
            m = pref[left_rem] % k
            freq[m] -= 1
        if right >= lo:
            target = pref[right] % k
            count += freq[target]
    return count

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError("m must be >= 1")
    count_even = [0] * m
    count_odd = [0] * m
    for v in values:
        r = v % m
        if v % 2 == 0:
            count_even[r] += 1
        else:
            count_odd[r] += 1

    def count_pairs(cnt: list[int]) -> int:
        res = 0
        for r in range(m):
            r2 = (m - r) % m
            if r < r2:
                res += cnt[r] * cnt[r2]
            elif r == r2:
                res += cnt[r] * (cnt[r] - 1) // 2
        return res

    return count_pairs(count_even) + count_pairs(count_odd)

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort(key=lambda x: (x[0], x[1]))
    current = 0
    max_load = 0
    earliest = 0
    i = 0
    n = len(events)
    while i < n:
        t = events[i][0]
        while i < n and events[i][0] == t:
            current += events[i][1]
            i += 1
        if current > max_load:
            max_load = current
            earliest = t
    return (max_load, earliest)

from collections import deque

def count_stable_windows(readings: list[int], tol: int) -> int:
    n = len(readings)
    if n == 0:
        return 0
    max_dq: deque[int] = deque()
    min_dq: deque[int] = deque()
    left = 0
    count = 0
    for right in range(n):
        while max_dq and readings[max_dq[-1]] <= readings[right]:
            max_dq.pop()
        max_dq.append(right)
        while min_dq and readings[min_dq[-1]] >= readings[right]:
            min_dq.pop()
        min_dq.append(right)
        while readings[max_dq[0]] - readings[min_dq[0]] > tol:
            left += 1
            if max_dq[0] < left:
                max_dq.popleft()
            if min_dq[0] < left:
                min_dq.popleft()
        count += right - left + 1
    return count

from bisect import bisect_right

def count_dominant_pairs(seq: list[int]) -> int:
    n = len(seq)
    if n < 2:
        return 0

    sorted_unique = sorted(set(seq))
    val_to_idx = {v: i for i, v in enumerate(sorted_unique)}
    m = len(sorted_unique)

    fenwick = [0] * (m + 1)

    def update(idx: int, delta: int) -> None:
        idx += 1
        while idx <= m:
            fenwick[idx] += delta
            idx += idx & -idx

    def prefix_sum(idx: int) -> int:
        idx += 1
        s = 0
        while idx > 0:
            s += fenwick[idx]
            idx -= idx & -idx
        return s

    def query_greater_than(x: int) -> int:
        i = bisect_right(sorted_unique, x)
        if i >= m:
            return 0
        total = prefix_sum(m - 1)
        before = prefix_sum(i - 1) if i > 0 else 0
        return total - before

    count = 0
    for val in seq:
        count += query_greater_than(3 * val)
        update(val_to_idx[val], 1)
    return count

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    order = []

    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}")

        category, amount, refunded = row

        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}")

        if amount < 0:
            raise ValueError(f"row {i}")

        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}")

        amount_f = float(amount)

        if category not in result:
            order.append(category)
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": amount_f,
            }

        summary = result[category]
        summary["count"] = summary["count"] + 1
        summary["gross"] = summary["gross"] + amount_f
        if not refunded:
            summary["net"] = summary["net"] + amount_f
        if amount_f > summary["largest"]:
            summary["largest"] = amount_f

    return {cat: result[cat] for cat in order}

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if (isinstance(low, bool) or isinstance(high, bool) or
            not isinstance(low, (int, float)) or
            not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    result = []
    for i in range(len(values)):
        v = values[i]
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("index {0}".format(i))
        if v < low:
            result.append(low)
        elif v > high:
            result.append(high)
        else:
            result.append(v)
    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Stack of (iterator, remaining_depth); process depth-first, left to right.
    stack = [(iter(nested), max_depth)]

    while stack:
        iterator, depth = stack[-1]
        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list) and depth > 0:
            stack.append((iter(item), depth - 1))
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text or text.isspace():
        raise ValueError("empty duration")

    n = len(text)
    i = 0
    total = 0
    seen_h = False
    seen_m = False
    seen_s = False
    last_order = -1

    while i < n:
        if not ('0' <= text[i] <= '9'):
            raise ValueError("malformed duration")

        start = i
        while i < n and '0' <= text[i] <= '9':
            i += 1
        value = int(text[start:i])

        if i >= n:
            raise ValueError("malformed duration")
        unit = text[i]
        i += 1

        if unit == 'h':
            order = 0
            if seen_h:
                raise ValueError("malformed duration")
            seen_h = True
            total += value * 3600
        elif unit == 'm':
            order = 1
            if seen_m:
                raise ValueError("malformed duration")
            seen_m = True
            total += value * 60
        elif unit == 's':
            order = 2
            if seen_s:
                raise ValueError("malformed duration")
            seen_s = True
            total += value
        else:
            raise ValueError("malformed duration")

        if order <= last_order:
            raise ValueError("malformed duration")
        last_order = order

    if not (seen_h or seen_m or seen_s):
        raise ValueError("malformed duration")

    return total

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    def is_name_char(ch):
        return (
            ('a' <= ch <= 'z')
            or ('A' <= ch <= 'Z')
            or ('0' <= ch <= '9')
            or ch == '_'
        )

    result = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
                continue
            start = i
            i += 1
            if i >= n:
                raise ValueError(
                    "unclosed placeholder at position " + str(start)
                )
            if template[i] == '}':
                raise ValueError(
                    "empty placeholder at position " + str(start)
                )
            name_chars = []
            while i < n and template[i] != '}':
                ch = template[i]
                if not is_name_char(ch):
                    raise ValueError(
                        "invalid placeholder at position " + str(start)
                    )
                name_chars.append(ch)
                i += 1
            if i >= n:
                raise ValueError(
                    "unclosed placeholder at position " + str(start)
                )
            name = ''.join(name_chars)
            if name not in context:
                raise KeyError(name)
            result.append(str(context[name]))
            i += 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
                continue
            raise ValueError("stray '}' at position " + str(i))
        else:
            result.append(c)
            i += 1

    return ''.join(result)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    stack = []

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i}")

        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"token {i}")
                # Truncate toward zero (not floor division).
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                stack.append(q)
        else:
            start = 0
            if len(token) > 0 and token[0] in "+-":
                start = 1
            if start >= len(token) or any(c not in "0123456789" for c in token[start:]):
                raise ValueError(f"unknown token at token {i}")
            stack.append(int(token))

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")

    def is_ascii_digits(s):
        if s == "":
            return False
        if s[0] not in "0123456789":
            return False
        if len(s) == 1:
            return True
        return is_ascii_digits(s[1:])

    def is_valid_index(s):
        if s == "":
            return False
        if s[0] == "-":
            return is_ascii_digits(s[1:])
        return is_ascii_digits(s)

    def navigate(node, segs):
        if len(segs) == 0:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return navigate(node[seg], rest)
        if isinstance(node, list):
            if not is_valid_index(seg):
                raise ValueError("invalid index")
            idx = int(seg)
            if idx >= len(node) or idx < -len(node):
                raise IndexError(seg)
            return navigate(node[idx], rest)
        raise TypeError("cannot descend")

    return navigate(data, segments)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0:
        return []

    counts = {}
    order = []
    for x in items:
        if x not in counts:
            counts[x] = 0
            order.append(x)
        counts[x] += 1

    n = len(order)
    if k > n:
        k = n

    used = [False] * n
    result = []
    for _ in range(k):
        best_i = None
        best_count = None
        for i in range(n):
            if used[i]:
                continue
            c = counts[order[i]]
            if best_i is None or c > best_count:
                best_i = i
                best_count = c
        used[best_i] = True
        val = order[best_i]
        result.append((val, counts[val]))

    return result
